def tandai_paket(apps, schema_editor):
    """Skenario bernama "Pn · ..." menjadi paket default berkode Pn dengan nama baru."""
    Skenario = apps.get_model("simulasi", "Skenario")
    terpakai = set()
    for sk in Skenario.objects.order_by("-diubah"):
        m = re.match(r"^(P\d) · ", sk.nama)
        if m and m.group(1) in NAMA_BARU and m.group(1) not in terpakai:
            terpakai.add(m.group(1))
            sk.templat = m.group(1)
            sk.kelompok = "bawaan"
            sk.nama, sk.singkat = NAMA_BARU[m.group(1)]
        else:
            sk.kelompok = "kustom"
        sk.save(update_fields=["templat", "kelompok", "nama", "singkat"])


